import json
from pathlib import Path

root = Path.cwd()
phase = root / "docs/artifacts/keyboard-circuit/phase1"

def replace(path, before, after):
    content = path.read_text(encoding="utf-8")
    assert before in content, str(path)
    path.write_text(content.replace(before, after, 1), encoding="utf-8", newline="\n")

brief = phase / "C08-REVIEW-BRIEF.md"
replace(brief, "- Both native models now carry", "- Startup now waits for all eight usable sound clips before movement and contact feedback begin. Loading resolves within the configured ten seconds, uses one canonical retry, and reports a playable degraded state if a clip fails. Waiting never queues old footsteps. The loading screen releases only its own movement action/render binding; another screen's control state is preserved.\n- Both native models now carry")
replace(brief, "Each multiplayer client also retains five initial misses before asynchronous preload finished; this startup gap existed in the C07 source pattern, but cold-load timing was not compared. No missed steps are replayed later.", "The earlier multiplayer receipt retains five initial misses per client before the readiness fix. Current [fresh startup](C08-readiness-startup-proof.json) resolved eight clips in 3.33 seconds with zero entries, plays or misses while loading. The character had not spawned during those observed loading frames; [actual-avatar stalled loading](C08-readiness-movement-fault-corrected-proof.json) blocks movement/jump in all 19 checks. [Five supported contacts](C08-readiness-first-steps.json) each produce a real playing voice with zero misses. No missed steps are replayed.")
replace(brief, "## Performance evidence", "## Startup readiness evidence\n\n[Corrected native fault fixture](C08-readiness-movement-fault-corrected-proof.json): a transient client copy with one invalid up ID and delayed preload resolves degraded at 1.20 seconds against its 1.2-second test deadline. Seven clips remain usable, current-foot feedback begins after resolution, surviving down voices play, and Stop/removal/replacement leave no old status, movement action or delayed playback. Previously disabled controls remain disabled. The earlier [movement fixture](C08-readiness-movement-fault-proof.json) is retained: its fixed 0.3-second expectation for a replacement loader was premature, and only the fixture was corrected. Production deadline remains ten seconds.\n\n[Native text layout](C08-readiness-status-layout.json) fits loading and fallback messages at simulated widths 320, 375 and 768. [Ten simulated lifecycle cases](research/C08-AUDIO-READINESS-SIMULATED-RECEIPT.json) cover canonical retry, preload exception, deadline, cancellation, removal and no late replay; they exercise a simulated scheduler rather than the engine. The new multiplayer launch joined zero clients after four minutes and was ended. Readiness has fresh solo/actual-avatar evidence; the earlier two-client shared-hold evidence remains separate. Native respawn during loading, restart on a live moving hazard, physical touch/gamepad, and network cold-cache timing were not measured.\n\n## Performance evidence")
replace(brief, "The pre-single-Enter source/native package is retained under `history/C08-before-single-enter/`.", "The pre-single-Enter source/native package is retained under `history/C08-before-single-enter/`. The full owner-accepted package before this readiness fix is recoverable under `history/C08-before-readiness/`.")
replace(brief, "A fresh five-judge release gate and owner checkpoint remain open before production expansion.", "The owner accepted the paired study/sample checkpoint; [acceptance record](C08-owner-checkpoint.json) identifies the preserved accepted package. At this input package's freeze, the fresh original-five gate is pending; its later independent reports and result are recorded in [C08 final gate](reviews/C08-FINAL-GATE.json). The three implementation specialists do not substitute for any judge. Mutable current status is kept in the course brief and review index outside the frozen inputs. Phase 2 remains on hold pending the gate and its separate final pass.")
replace(brief, "For the owner check, start Studio Play, stage the sample with its existing Begin hook, stand still, walk diagonally, jump/re-enter, and try both Enter arms.", "For a manual retest, start Studio Play, stage the sample with its existing Begin hook, wait for key sounds, stand still, walk diagonally, jump/re-enter, and try both Enter arms.")
replace(brief, "Keep Phase 2/3 separate until the paired study/sample checkpoint is accepted.", "The paired checkpoint is accepted; Phase 2/3 production remains separate.")

replace(phase / "EVIDENCE.md", "Warm audio played all four families without extra misses or steals; five early preload misses on each multiplayer client remain recorded. Native frame captures did not show a measurable CPU/FPS gain. Human sound/feel judgment and the fresh five-judge release gate remain open.", "Warm audio played all four families without extra misses or steals. Earlier initial misses remain historical; bounded startup now has fresh solo, five actual voice-playback contacts, stalled-clip movement/cleanup and narrow-layout evidence. Native frame captures did not show a measurable CPU/FPS gain. The owner checkpoint is accepted. At input freeze, the fresh original-five gate is pending; its later result is in [C08 final gate](reviews/C08-FINAL-GATE.json).")
replace(phase / "ASSET_CATALOG.md", "Native warmed fixtures recorded no missing clips or voice steals; initial preload misses are retained. Human family selection remains open.", "Native warmed fixtures recorded no missing clips or voice steals. Startup now has bounded readiness, an explicit failed-clip fallback and five actual first-contact voices without misses. Earlier preload misses remain historical. Owner Phase 1 acceptance is recorded; repeated listening comfort remains unmeasured.")
replace(phase / "audio/README.md", "Each also retains five initial skipped hits before asynchronous preload finished. C07 used the same preload/skip pattern; cold-load duration was not compared, and missed steps are not queued later.", "The earlier receipt retains five initial skipped hits per client before this fix. Current startup waits for eight usable clips, with one canonical retry and a ten-second bound. Fresh solo startup and five actual supported contacts have zero misses; the stalled-clip test keeps usable sounds/visuals, restores movement and reports fallback without replaying old events. C07 used the old asynchronous preload/skip pattern; network cold-cache duration and fresh two-client readiness were not measured.")

course = root / "docs/artifacts/keyboard-circuit/COURSE_BRIEF.md"
content = course.read_text(encoding="utf-8")
lines = content.splitlines()
replacement = {
    "- **Status:**": "- **Status:** C08's owner checkpoint is accepted. The follow-up fixes startup audio readiness with a bounded ten-second loading step and playable failed-clip fallback, preserving accepted geometry, key feel and sound treatment. All fourteen sources, native rebuilding/reopening, fresh solo startup, five real first-contact voices, stalled-clip movement/cleanup and narrow text layouts passed. The fresh original-five review gate is pending. Phase 2 stays on hold.",
    "- **Checkpoint:**": "- **Checkpoint:** the owner accepted the paired cheap whole-route study and finished Thocky sample, conveyed by the Course Ideation chat. [Acceptance record](phase1/C08-owner-checkpoint.json) and the full pre-readiness package preserve that decision. Technical reviewer scores remain separate.",
    "- **Next action:**": "- **Next action:** complete fresh independent review by the same five High judges on the final frozen C08 package; each must score at least 8.5 with zero blockers. [C08 final gate](phase1/reviews/C08-FINAL-GATE.json) records their later results. Keep Phase 2 on hold for its separate final pass; no production expansion, whole-place save or publication is authorized.",
    "- **Operations / reviews in flight:**": "- **Operations / reviews in flight:** source/native readiness work is complete; original-five reviews are next. Studio is back in Edit with the owner's view restored within Studio rotation precision. Earlier initial audio misses are retained as historical evidence. A new multiplayer launch joined zero clients and was ended; fresh readiness evidence is solo/actual-avatar. [C08 evidence](phase1/C08-REVIEW-BRIEF.md) separates native, simulated and historical checks. No CPU/FPS gain, device/full-race result, whole-place save or publication is claimed.",
}
for index, line in enumerate(lines):
    for prefix, value in replacement.items():
        if line.startswith(prefix): lines[index] = value
course.write_text("\n".join(lines) + "\n", encoding="utf-8", newline="\n")
replace(phase / "reviews/INDEX.md", "A fresh review by the same five High judges and the separate owner study/sample checkpoint remain open before production expansion.", "The owner accepted the paired study/sample checkpoint. A fresh review by the same five High judges is pending on the frozen readiness package; [C08 final gate](C08-FINAL-GATE.json) records their later independent results. Phase 2 stays on hold for its separate final pass.")

gate = {"candidate": "KC_P1_C08", "kitRevision": "KC_KIT_C08_01", "status": "awaiting_frozen_review", "ownerCheckpointAccepted": True, "originalIndependentReviewerCount": 5, "eachRequiredScore": 8.5, "reviews": [], "reviewGatePassed": False, "historicalScoresInherited": False, "phase2": "on hold", "wholePlaceSaved": False, "published": False}
(phase / "reviews/C08-FINAL-GATE.json").write_text(json.dumps(gate, indent=2) + "\n", encoding="utf-8", newline="\n")
for path, text in {
    "docs/DECISIONS.md": "C08 startup waits for eight usable clips before local movement/contact feedback. One canonical retry and a ten-second deadline resolve to ready or explicit degraded play; no old footstep queue. Server gameplay and accepted sound treatment are retained. The owner checkpoint is accepted; the original five review independently on frozen inputs, with later reports/status audited separately.",
    "docs/BUGS.md": "C08 initial unloaded-hit gap fixed by bounded entry readiness. Fresh solo startup and five actual voices record zero misses; a stalled-clip fixture verifies held visuals, movement restoration and cleanup. Earlier startup misses remain archived; physical devices, network cold-cache and fresh multiplayer readiness are not verified.",
    "docs/TASKS.md": "C08 owner checkpoint accepted; readiness source/native checks complete. Pending: fresh independent original-five gate, each >=8.5 with no blockers. Phase 2 final pass remains on hold; no whole-place save/publication authorization.",
    "docs/PLAYTEST_NOTES.md": "C08 readiness: fresh solo eight clips resolved in 3.33s; observed loading frames had no character yet and zero entries/plays/misses. Five supported actual-avatar contacts each emitted a playing voice. Stalled-clip fixture blocked movement/jump in 19/19 checks, resolved a 1.2s test deadline, retained seven sounds, restored movement, preserved disabled controls, and cleaned Stop/switch. Loading/fallback text fits simulated widths 320/375/768. Ten scheduler-simulated audio lifecycle cases passed. A new two-client launch had zero joined clients after four minutes and was ended. No fresh native respawn-on-loading, live-hazard restart, touch/gamepad or cold-cache result is claimed.",
}.items():
    with (root / path).open("a", encoding="utf-8", newline="\n") as stream:
        stream.write("\n### Keyboard Circuit C08 readiness - October 7, 2026\n\n" + text + "\n")
print("C08 readiness/acceptance documentation updated; frozen input gate remains pending until original-five reports")
